export const politica = {
  informe: "Informe de asignación de costos",
  agruparPor: ["Proyecto", "CentroDeCostos", "aws:createdBy"],
  etiquetas: [
    { clave: "Proyecto", tipo: "DEFINIDA_POR_EL_USUARIO", aplicada: true, activada: true },
    { clave: "CentroDeCostos", tipo: "DEFINIDA_POR_EL_USUARIO", aplicada: true, activada: true },
    { clave: "aws:createdBy", tipo: "GENERADA_POR_AWS", aplicada: true, activada: true },
  ],
};

spec.code:
for (const clave of politica.agruparPor) {
  const etiqueta = politica.etiquetas.find((e) => e.clave === clave);
  assert.ok(etiqueta, clave + " debe existir en la lista de etiquetas");
  assert.strictEqual(etiqueta.activada, true, clave + " debe estar activada");
}

for (const etiqueta of politica.etiquetas) {
  assert.strictEqual(etiqueta.aplicada, true, etiqueta.clave + " debe seguir aplicada");
}

const esperado = {
  Proyecto: "DEFINIDA_POR_EL_USUARIO",
  CentroDeCostos: "DEFINIDA_POR_EL_USUARIO",
  "aws:createdBy": "GENERADA_POR_AWS",
};
for (const [clave, tipo] of Object.entries(esperado)) {
  const etiqueta = politica.etiquetas.find((e) => e.clave === clave);
  assert.ok(etiqueta, clave + " debe seguir existiendo");
  assert.strictEqual(etiqueta.tipo, tipo);
}

