export type Notificacion = {
  id: string;
  tipo: "REAL" | "PREVISTO";
  umbralPorcentaje: number;
};

export type Presupuesto = {
  importe: number;
  notificaciones: Notificacion[];
};

export type Gasto = {
  actual: number;
  previsto: number;
};

export function notificacionesDisparadas(presupuesto: Presupuesto, gasto: Gasto): string[] {
  const disparadas: string[] = [];
  for (const notificacion of presupuesto.notificaciones) {
    const umbral = presupuesto.importe * (notificacion.umbralPorcentaje / 100);
    const medida = notificacion.tipo === "REAL" ? gasto.actual : gasto.previsto;
    if (medida >= umbral) {
      disparadas.push(notificacion.id);
    }
  }
  return disparadas;
}

spec.code:
const presupuesto = {
  importe: 1000,
  notificaciones: [
    { id: "real-80", tipo: "REAL" as const, umbralPorcentaje: 80 },
    { id: "previsto-100", tipo: "PREVISTO" as const, umbralPorcentaje: 100 },
  ],
};
assert.deepStrictEqual(notificacionesDisparadas(presupuesto, { actual: 500, previsto: 1100 }), ["previsto-100"]);

const presupuesto = {
  importe: 1000,
