  ],
};
assert.deepStrictEqual(notificacionesDisparadas(presupuesto, { actual: 800, previsto: 1000 }), ["real-80", "previsto-100"]);

const presupuesto = {
  importe: 1000,
  notificaciones: [
    { id: "real-80", tipo: "REAL" as const, umbralPorcentaje: 80 },
    { id: "previsto-100", tipo: "PREVISTO" as const, umbralPorcentaje: 100 },
  ],
};
const antes = JSON.stringify(presupuesto);
notificacionesDisparadas(presupuesto, { actual: 900, previsto: 1200 });
assert.strictEqual(JSON.stringify(presupuesto), antes);
